#pragma once

#include <modm/ext/canard/canard.hpp>
#include <dronecan/canard.h>
#include <chrono>
#include <concepts>

/// Helpers for the code generated by the `modm:ext:dronecan` module
namespace modm::dronecan
{

/// Wraps a payload received by libcanard for the `*_decode()` functions of the
/// generated code, which return true if the payload is invalid.
inline CanardRxTransfer
transfer(const canard_payload_t& payload)
{
	CanardRxTransfer transfer{};
	// without middle and tail blocks the payload is read contiguously
	transfer.payload_head = static_cast<const uint8_t*>(payload.view.data);
	transfer.payload_len = payload.view.size;
	return transfer;
}

/// CRC seed of a data type signature, e.g. `UAVCAN_PROTOCOL_GETNODEINFO_SIGNATURE`,
/// for canard_v0_publish(), canard_v0_subscribe() and the service functions.
inline uint16_t
crcSeed(uint64_t signature)
{
	return canard_v0_crc_seed_from_data_type_signature(signature);
}

/// Constants and functions of a generated type, specialized in its header:
/// `id` (if it has a default data type ID), `signature`, `max_size`,
/// `encode()`, `decode()`, and for a service the `Request` or `Response` type.
template< class T >
struct Type;

template< class T >
concept Message = requires { Type<T>::id; } and
	not requires { typename Type<T>::Request; } and not requires { typename Type<T>::Response; };
template< class T >
concept Request = requires { Type<T>::id; typename Type<T>::Response; };
template< class T >
concept Response = requires { Type<T>::id; typename Type<T>::Request; };

/// Decodes a received payload into a message, request or response.
/// @return true if the payload is valid
template< class T >
bool
decode(const canard_payload_t& payload, T& value)
{
	const CanardRxTransfer t = transfer(payload);
	return not Type<T>::decode(t, value);
}

/// Publishes a message and increments the transfer-ID on success.
template< Message T >
bool
publish(canard_t* canard, const T& message, uint8_t& transfer_id,
		canard_prio_t priority = canard_prio_nominal,
		std::chrono::microseconds timeout = std::chrono::seconds(1))
{
	uint8_t buffer[Type<T>::max_size];
	const uint32_t size = Type<T>::encode(message, buffer);
	if (not canard_v0_publish(canard, canard::now() + timeout.count(), CANARD_IFACE_BITMAP_ALL, priority,
			Type<T>::id, crcSeed(Type<T>::signature), transfer_id, {{size, buffer}, nullptr}, nullptr))
		return false;
	transfer_id = (transfer_id + 1) % CANARD_TRANSFER_ID_MODULO;
	return true;
}

/// Publishes an anonymous message of up to 7 bytes, see Node::publishAnonymous().
template< Message T, class Node >
bool
publishAnonymous(Node& node, const T& message, uint8_t& transfer_id,
				 canard_prio_t priority = canard_prio_nominal)
{
	uint8_t buffer[Type<T>::max_size];
	const uint32_t size = Type<T>::encode(message, buffer);
	if (not node.publishAnonymous(Type<T>::id, transfer_id, {buffer, size}, priority)) return false;
	transfer_id = (transfer_id + 1) % CANARD_TRANSFER_ID_MODULO;
	return true;
}

/// Sends a request to a server and increments the transfer-ID on success.
template< Request T >
bool
request(canard_t* canard, uint8_t server, const T& request, uint8_t& transfer_id,
		canard_prio_t priority = canard_prio_nominal,
		std::chrono::microseconds timeout = std::chrono::seconds(1))
{
	uint8_t buffer[Type<T>::max_size];
	const uint32_t size = Type<T>::encode(request, buffer);
	if (not canard_v0_request(canard, canard::now() + timeout.count(), priority, Type<T>::id,
			crcSeed(Type<T>::signature), server, transfer_id, {{size, buffer}, nullptr}, nullptr))
		return false;
	transfer_id = (transfer_id + 1) % CANARD_TRANSFER_ID_MODULO;
	return true;
}

/// Responds to the request of a client with its transfer-ID.
template< Response T >
bool
respond(canard_t* canard, uint8_t client, uint8_t transfer_id, const T& response,
		canard_prio_t priority = canard_prio_nominal,
		std::chrono::microseconds timeout = std::chrono::seconds(1))
{
	uint8_t buffer[Type<T>::max_size];
	const uint32_t size = Type<T>::encode(response, buffer);
	return canard_v0_respond(canard, canard::now() + timeout.count(), priority, Type<T>::id,
			crcSeed(Type<T>::signature), client, transfer_id, {{size, buffer}, nullptr}, nullptr);
}

/// Subscribes to a message.
template< Message T >
canard_subscription_t*
subscribe(canard_t* canard, canard_subscription_t* subscription,
		  const canard_subscription_vtable_t* vtable,
		  canard_us_t transfer_id_timeout = CANARD_DEFAULT_TRANSFER_ID_TIMEOUT_us)
{
	return canard_v0_subscribe(canard, subscription, Type<T>::id, crcSeed(Type<T>::signature),
							   Type<T>::max_size, transfer_id_timeout, vtable);
}

/// Subscribes to the requests of a service as server.
template< Request T >
canard_subscription_t*
subscribe(canard_t* canard, canard_subscription_t* subscription,
		  const canard_subscription_vtable_t* vtable,
		  canard_us_t transfer_id_timeout = CANARD_DEFAULT_TRANSFER_ID_TIMEOUT_us)
{
	return canard_v0_subscribe_request(canard, subscription, Type<T>::id, crcSeed(Type<T>::signature),
									   Type<T>::max_size, transfer_id_timeout, vtable);
}

/// Subscribes to the responses of a service as client.
template< Response T >
canard_subscription_t*
subscribe(canard_t* canard, canard_subscription_t* subscription,
		  const canard_subscription_vtable_t* vtable)
{
	return canard_v0_subscribe_response(canard, subscription, Type<T>::id, crcSeed(Type<T>::signature),
										Type<T>::max_size, vtable);
}

/// Metadata of a transfer received by a typed subscription
struct Transfer
{
	canard_us_t timestamp;
	canard_prio_t priority;
	uint8_t source;
	uint8_t transfer_id;
	/// The `context` of subscribe()
	void* context;
};

/**
 * Subscribes to a message, the requests of a service as server or its
 * responses as client, and calls `callback(const Transfer&, const T&)` with
 * every valid transfer. The payload is decoded on the stack and released
 * before the call, invalid payloads are dropped. Like all subscription
 * callbacks, the callback must not call libcanard, so store what it needs and
 * respond or publish later.
 *
 * @return false if libcanard is out of memory or the type is already subscribed
 */
template< class T, auto callback >
requires std::invocable<decltype(callback), const Transfer&, const T&>
bool
subscribe(canard_t* canard, canard_subscription_t* subscription, void* context = nullptr)
{
	static constexpr canard_subscription_vtable_t vtable{
		[](canard_subscription_t* sub, canard_us_t timestamp, canard_prio_t priority,
		   uint_least8_t source, uint_least8_t transfer_id, canard_payload_t payload)
		{
			T value;
			const bool valid = decode(payload, value);
			canard::release(sub, payload);
			if (valid) callback(Transfer{timestamp, priority, uint8_t(source), uint8_t(transfer_id),
										 sub->user_context}, value);
		}};
	if (subscribe<T>(canard, subscription, &vtable) != subscription) return false;
	subscription->user_context = context;
	return true;
}

} // namespace modm::dronecan
